@extends('layouts.app') @section('content')<div class="card"><h1>{{$task->title}}</h1><p>{{$task->description}}</p><p><span class="badge">{{$task->priority}}</span> <span class="badge">{{$task->status}}</span> Deadline: {{$task->due_date?->format('d-m-Y')??'-'}}</p><a class="btn" href="{{route('tasks.edit',$task)}}">Edit</a>@if($task->status!=='done')<form class="inline" method="POST" action="{{route('tasks.done',$task)}}">@csrf @method('PATCH')<button>Selesaikan</button></form>@endif<form class="inline" method="POST" action="{{route('tasks.destroy',$task)}}">@csrf @method('DELETE')<button class="danger">Hapus</button></form></div><div class="card"><h2>Anggota Tugas</h2><form method="POST" action="{{route('tasks.members.add',$task)}}">@csrf<select name="user_id" required><option value="">Pilih user</option>@foreach($users as $u)<option value="{{$u->id}}">{{$u->name}} ({{$u->email}})</option>@endforeach</select><select name="member_status"><option value="pending">pending</option><option value="accepted">accepted</option><option value="rejected">rejected</option></select><button>Tambah Anggota</button></form>@foreach($task->members as $m)<p>{{$m->user->name}} - <span class="badge">{{$m->member_status}}</span><form class="inline" method="POST" action="{{route('tasks.members.remove',[$task,$m->user_id])}}">@csrf @method('DELETE')<button class="danger">Hapus</button></form></p>@endforeach</div>@endsection
